import { rehypeCodeDefaultOptions, remarkMdxMermaid } from 'fumadocs-core/mdx-plugins';
import { defineConfig, defineDocs } from 'fumadocs-mdx/config';
import type { ShikiTransformer } from 'shiki';
import { codeDark, codeLight } from './lib/code-themes';

// content/docs/ is generated by scripts/content.mjs from badil's docs at the pinned tag.
export const docs = defineDocs({
  dir: 'content/docs',
});

// The fence's language on <pre>, for the code frame's bar (components/mdx/code-frame.tsx).
const languageAttribute: ShikiTransformer = {
  name: 'badil:data-language',
  pre(node) {
    node.properties['data-language'] = this.options.lang;
  },
};

// ```mermaid blocks become <Mermaid chart="…" /> (components/mdx/mermaid.tsx).
export default defineConfig({
  mdxOptions: {
    remarkPlugins: [remarkMdxMermaid],
    rehypeCodeOptions: {
      themes: { light: codeLight, dark: codeDark },
      transformers: [...(rehypeCodeDefaultOptions.transformers ?? []), languageAttribute],
      // The code frame draws its own bar.
      icon: false,
    },
  },
});
